fn main() {
    // 1. reads: borrows immutably, so list is still usable
    let list = vec![1, 2, 3];
    let only_borrows = || println!("From closure: {list:?}");
    println!("Before calling closure: {list:?}");
    only_borrows();
    println!("After calling closure: {list:?}");

    // 2. changes: borrows mutably, so no other use until its last call
    let mut list = vec![1, 2, 3];
    let mut borrows_mutably = || list.push(7);
    borrows_mutably();
    println!("After calling closure: {list:?}");

    // 3. consumes: takes ownership
    let words = vec![String::from("a"), String::from("b")];
    let consume = || words; // returns the vector, moving it
    let v = consume();
    println!("moved out: {v:?}");
}

