fn apply_twice<F: Fn(i32) -> i32>(f: F, x: i32) -> i32 {
    f(f(x))
}

fn make_adder(n: i32) -> impl Fn(i32) -> i32 {
    move |x| x + n
}

fn call_n_times(mut f: impl FnMut(), n: usize) {
    for _ in 0..n {
        f();
    }
}

fn main() {
    let add_five = make_adder(5);
    println!("{}", apply_twice(&add_five, 1));
    println!("{}", apply_twice(|x| x * x, 3));

    let mut count = 0;
    call_n_times(|| count += 2, 4);
    println!("count = {count}");
}

fn apply_discounts<F: Fn(f64) -> f64>(prices: &[f64], rule: F) -> Vec<f64> {
    let mut out = Vec::new();
    for &p in prices {
        out.push(rule(p));
    }
    out
}

